import type { Html, Link, Nodes, Parent, PhrasingContent, Root } from 'mdast'

/**
 * `<a href="…">text</a>` written inside markdown becomes a markdown LINK — and nothing else of HTML
 * does.
 *
 * WHY. Reports generated by standard tools (a Trivy template, a test report) write their links as
 * HTML anchors, and the widget showed them as literal text: raw HTML is never rendered here. The
 * request was links, not HTML, so this does not turn raw HTML on (no rehype-raw, no sanitizer to keep
 * in step with it). It rewrites one shape, an opening `<a>` tag, its phrasing, and the matching
 * `</a>` in the same paragraph or table cell, into the `link` node `[text](href)` would have made.
 * From there it is an ordinary markdown link: the widget's `a` renderer decides the tab, `rel` and
 * routing, and react-markdown's URL filter still runs.
 *
 * Only `href` is read; `target`, `rel`, `onclick`, `style` and the rest are dropped. The href must be
 * an absolute http, https or mailto URL, in quotes. Anything else — another tag, an anchor with a
 * `javascript:` or relative href, an `<a>` with no `</a>` beside it — is left alone, so it still shows
 * as text, as all raw HTML did before.
 *
 * Quotes: `<a href=https://…>` (unquoted) never reaches this plugin as a tag. GFM's autolink literal
 * claims the bare URL first and runs it up to the next space, so the parser sees `<a href=` as text,
 * a link to `https://…>label`, and a stray `</a>` — a mangled link, which this plugin does not try to
 * repair. Report generators quote their attributes; hand-written anchors must too.
 */

const ALLOWED_PROTOCOLS = new Set(['http:', 'https:', 'mailto:'])

/** Where inline HTML can sit beside phrasing. A block-level `<a>` (alone on its line) is not touched. */
const INLINE_PARENTS = new Set(['delete', 'emphasis', 'heading', 'paragraph', 'strong', 'tableCell'])

const OPEN_TAG = /^<a(?:\s[^]*)?>$/i
const CLOSE_TAG = /^<\/a\s*>$/i

/** The href of one opening `<a …>` tag, or null when it is not one we accept. */
const parseOpenTag = (value: string): string | null => {
  if (!OPEN_TAG.test(value)) { return null }
  // The browser's own parser reads the attributes (quoting, entities such as `&amp;`). A parsed
  // document is inert: nothing in it runs or loads, and only the href is taken out of it.
  const element = new DOMParser().parseFromString(value, 'text/html').body.firstElementChild
  if (element?.tagName !== 'A') { return null }
  const href = element.getAttribute('href')?.trim()
  if (!href) { return null }
  let url: URL
  try {
    url = new URL(href)
  } catch {
    return null
  }
  if (!ALLOWED_PROTOCOLS.has(url.protocol)) { return null }
  return href
}

const isHtml = (node: Nodes): node is Html => node.type === 'html'

const containsLink = (nodes: readonly Nodes[]): boolean => nodes.some((node) => (
  node.type === 'link' || ('children' in node && containsLink(node.children))
))

const rewrite = (parent: Parent) => {
  if (INLINE_PARENTS.has(parent.type)) {
    const children = parent.children as PhrasingContent[]
    for (let open = 0; open < children.length; open++) {
      const node = children[open]
      const href = isHtml(node) ? parseOpenTag(node.value) : null
      if (!href) { continue }
      const close = children.findIndex((candidate, index) => index > open && isHtml(candidate) && CLOSE_TAG.test(candidate.value))
      if (close === -1) { continue }
      const inner = children.slice(open + 1, close)
      // A link inside a link is not a link: leave the whole thing as written.
      if (containsLink(inner)) { continue }
      const link: Link = { children: inner, type: 'link', url: href }
      children.splice(open, close - open + 1, link)
    }
  }
  for (const child of parent.children) {
    if ('children' in child) { rewrite(child) }
  }
}

const remarkHtmlAnchors = () => (tree: Root) => {
  rewrite(tree)
}

export default remarkHtmlAnchors
